<script setup lang="ts">import GText from '../../content/GText/GText.vue'; import type { TextContent } from '@/shared/types/components'; import { useLocalizedText } from '@/shared/composables/localization/useLocalizedText'; const props = withDefaults(defineProps<{ modelValue?: number; pages?: number; disabled?: boolean; label?: TextContent; previousLabel?: TextContent; nextLabel?: TextContent }>(), { modelValue: 1, pages: 1, label: () => ({ table: 'Common', textKey: '#PAGINATION' }), previousLabel: () => ({ table: 'Common', textKey: '#PREVIOUS' }), nextLabel: () => ({ table: 'Common', textKey: '#NEXT' }) }); const labelText = useLocalizedText(() => props.label); const emit = defineEmits<{ 'update:modelValue': [value: number]; change: [value: number] }>(); function go(value: number) { emit('update:modelValue', value); emit('change', value) }</script>
<template><nav class="ew-pagination" :aria-label="labelText"><button class="ew-button" type="button" :disabled="disabled || modelValue <= 1" @click="go(modelValue - 1)"><GText :content="previousLabel" /></button><span aria-current="page">{{ modelValue }} / {{ pages }}</span><button class="ew-button" type="button" :disabled="disabled || modelValue >= pages" @click="go(modelValue + 1)"><GText :content="nextLabel" /></button></nav></template>
